        title = LocalizedText("""Novena de liberación de maldiciones ancestrales""", """Release from Ancestral Curses Novena""", """Novena de libertação das maldições ancestrais"""),
        patron = LocalizedText("""Santo patrón de las maldiciones ancestrales, los espíritus generacionales""", """Patron saint of ancestral curses, generational spirits""", """Novena de libertação das maldições ancestrais"""),
        category = LocalizedText("""Novenas""", """Novenas""", """Novenas"""),
        description = LocalizedText("""Reza contra los espíritus generacionales y las maldiciones ancestrales.""", """Pray against generational spirits and ancestral curses.""", """Santo padroeiro de as maldições ancestrais e os espíritos geracionais"""),
